src='def transform(grid):
    g = [row[:] for row in grid]
    rows = [i for i, row in enumerate(g) if any(row)]
    bands = []
    for r in rows:
        if not bands or r > bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)
    for band in bands:
        r = band[0]
        cols = [j for j, value in enumerate(g[r]) if value]
        if cols:
            for j in range(max(cols) + 1, len(g[r])):
                if g[r][j] == 0:
                    g[r][j] = 1
    return g
'
